/** S5-R26: the only link labels a concept map may use. */
export const CONCEPT_LINKS = [
  'causes',
  'leads to',
  'is part of',
  'is a type of',
  'produces',
  'needs',
  'prevents',
  'increases',
  'decreases',
  'is found in',
  'carries',
  'controls',
] as const;
export type ConceptLink = (typeof CONCEPT_LINKS)[number];

export interface Labelled {
  id: string;
  label: string;
}

export interface ClassifyData {
  bins: Labelled[];
  items: Array<
    Labelled & {
      /** id of the bin the item belongs to */
      bin: string;
      /** curriculum misconception a wrong placement would reveal */
      misconception_id?: string;
      /** shown when the item is placed wrongly */
      feedback?: string;
    }
  >;
}

export interface MatchData {
  left: Labelled[];
  /** may contain extra distractors that pair with nothing */
  right: Labelled[];
  /** [leftId, rightId] — exactly one per left item */
  pairs: Array<[string, string]>;
}

export interface SequenceData {
  /** stored in the CORRECT order; the client shuffles for display */
  steps: Labelled[];
}

export interface NumericStep {
  prompt: string;
  /** mathjs expression over `variables` and earlier steps (s1, s2, …) */
  expression: string;
  /** computed and stamped by the server, never trusted from the model */
  answer: number;
  unit?: string;
  /** absolute tolerance; default = 1% of |answer| (min 1e-9) */
  tolerance?: number;
}

export interface NumericSolverData {
  context: string;
  variables: Record<string, number>;
  steps: NumericStep[];
}

// ── table_complete (S5-R23) ─────────────────────────────────────────────────

export type TableCell =
  | { given: string }
  | {
      id: string;
      blank: 'number';
      /** mathjs expression over the table's `variables` */
      expression: string;
      /** stamped by the server */
      answer: number;
      unit?: string;
      tolerance?: number;
    }
  | {
      id: string;
      blank: 'text';
      /** normalised comparison: spacing and punctuation ignored; case too unless case_sensitive */
      accepted: string[];
      /** genotypes, chemical symbols: "Tt" ≠ "TT", "Co" ≠ "CO" */
      case_sensitive?: boolean;
    };

export interface TableCompleteData {
  context: string;
  columns: string[];
  rows: Array<{ cells: TableCell[] }>;
  variables: Record<string, number>;
  /** when present the server generated the grid from these genotypes */
  punnett?: { parent1: string; parent2: string };
}

// ── label_flow (S5-R24) ─────────────────────────────────────────────────────

export interface LabelFlowData {
  /** a node is either shown (label) or a blank the student fills */
  nodes: Array<{ id: string; label?: string; blank?: boolean }>;
  edges: Array<{ from: string; to: string; label?: string }>;
  /** the label bank, including distractors */
  labels: Labelled[];
  /** [blankNodeId, labelId] */
  answers: Array<[string, string]>;
  cycle?: boolean;
}

// ── highlight_evidence (S5-R25) ─────────────────────────────────────────────

export interface HighlightEvidenceData {
  /** what to find, e.g. "Select the sentences that show Okot is generous" */
  task: string;
  /** the passage split into sentences by the server */
  units: Array<{ id: string; text: string }>;
  /** ids of the target sentences */
  targets: string[];
  /** optional per-target note shown after checking */
  notes?: Record<string, string>;
}

// ── concept_map (S5-R26) ────────────────────────────────────────────────────

export interface ConceptMapData {
  nodes: Labelled[];
  edges: Array<{ id: string; from: string; to: string; label: ConceptLink }>;
}

// ── graph_plot (S5-R27) ─────────────────────────────────────────────────────

export interface GraphGrid {
  xmin: number;
  xmax: number;
  ymin: number;
  ymax: number;
  step: number;
}

export interface GraphPlotData {
  context: string;
  grid: GraphGrid;
  mode: 'points' | 'line';
  /** points mode: the function and the stamped points to plot */
  expression?: string;
  points?: Array<[number, number]>;
  /** line mode: each line's equation with stamped slope/intercept (y = m·x + c) */
  lines?: Array<{
    id: string;
    label: string;
    expression: string;
    m: number;
    c: number;
  }>;
}

// ── slider_explorer (S5-R28) ────────────────────────────────────────────────

export interface SliderParam {
  name: string;
  label: string;
  min: number;
  max: number;
  step: number;
  initial: number;
  unit?: string;
}

export interface SliderExplorerData {
  context: string;
  params: SliderParam[];
  output: { expression: string; label: string; unit?: string };
  /** output for every parameter combination, row-major in params order (stamped) */
  table: number[];
  questions: Array<{
    id: string;
    prompt: string;
    at: Record<string, number>;
    /** stamped from the table */
    answer: number;
    tolerance?: number;
  }>;
}

// ── scenario_decision (S5-R29) ──────────────────────────────────────────────

export interface ScenarioDecisionData {
  setting: string;
  decisions: Array<{
    id: string;
    prompt: string;
    options: Array<{
      id: string;
      label: string;
      consequence: string;
      verdict: 'best' | 'ok' | 'poor';
      misconception_id?: string;
    }>;
  }>;
}

// ── label_diagram (S5-R30) ──────────────────────────────────────────────────

export interface LabelDiagramData {
  /** storage key; the URL is refreshed on every lesson start */
  image_key: string;
  image_url?: string;
  /**
   * box_2d = [ymin, xmin, ymax, xmax], normalised 0-1000. `marker` = where the
   * tap target sits ([y, x], 0-1000), spread by the server so markers never
   * overlap on a phone (S5-R30).
   */
  hotspots: Array<{
    id: string;
    box: [number, number, number, number];
    marker?: [number, number];
  }>;
  /** parts + distractors */
  labels: Labelled[];
  /** [hotspotId, labelId] */
  answers: Array<[string, string]>;
}

