// ── Student responses ────────────────────────────────────────────────────────

export interface ClassifyResponse {
  /** itemId → binId */
  placements: Record<string, string>;
}
export interface MatchResponse {
  /** leftId → rightId */
  pairs: Record<string, string>;
}
export interface SequenceResponse {
  /** step ids in the student's order */
  order: string[];
}
export interface NumericResponse {
  /** one entry per step, in order; null = not answered */
  values: Array<number | null>;
}

export interface TableResponse {
  /** cellId → what the student typed */
  values: Record<string, string>;
}
/** label_flow and label_diagram: blank/hotspot id → label id */
export interface PlacementResponse {
  placements: Record<string, string>;
}
export interface HighlightResponse {
  /** selected sentence ids */
  selected: string[];
}
export interface ConceptMapResponse {
  links: Array<{ from: string; to: string; label: string }>;
}
export interface GraphResponse {
  /** points mode: tapped lattice points */
  points?: Array<[number, number]>;
  /** line mode: lineId → two tapped points */
  lines?: Record<string, Array<[number, number]>>;
}
/** slider_explorer answers (one per question, like numeric) */
export interface SliderResponse {
  values: Array<number | null>;
}
export interface ScenarioResponse {
  /** decisionId → optionId */
  choices: Record<string, string>;
}

export type InteractionResponse =
  | ClassifyResponse
  | MatchResponse
  | SequenceResponse
  | NumericResponse
  | TableResponse
  | PlacementResponse
  | HighlightResponse
  | ConceptMapResponse
  | GraphResponse
  | SliderResponse
  | ScenarioResponse;

export interface ItemResult {
  /** item / left / step id, or the step index as a string for numeric */
  id: string;
  correct: boolean;
  /** what the correct answer is, as a label, for the reveal */
  expected: string;
  misconception_id?: string;
  feedback?: string;
}

export interface CheckResult {
  /** 0..1, share of items correct */
  score: number;
  items: ItemResult[];
  misconception_hits: string[];
}
